import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"32、【恆】 巽下震上","description":"溫公易說 - 32、【恆】 巽下震上","frontmatter":{"title":"32、【恆】 巽下震上","description":"溫公易說 - 32、【恆】 巽下震上"},"headers":[],"relativePath":"classics/wengong/033.md","filePath":"classics/wengong/033.md"}'),l={name:"classics/wengong/033.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_32、【恆】-巽下震上" tabindex="-1">32、【恆】 巽下震上 <a class="header-anchor" href="#_32、【恆】-巽下震上" aria-label="Permalink to “32、【恆】 巽下震上”">​</a></h1><h3 id="彖曰-恆-久也。剛上而柔下-雷風相與-巽而動-剛柔皆應-恆亨無咎-利貞。久於其道也。天地之道-恆久而不已也。利有攸往-終則有始也。日月得天而能久照-四時變化而能久成。聖人久於其道而天下化成。觀其所恆-而天地萬物之情可見矣。" tabindex="-1">彖曰：恆，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆亨無咎，利貞。久於其道也。天地之道，恆久而不已也。利有攸往，終則有始也。日月得天而能久照，四時變化而能久成。聖人久於其道而天下化成。觀其所恆，而天地萬物之情可見矣。 <a class="header-anchor" href="#彖曰-恆-久也。剛上而柔下-雷風相與-巽而動-剛柔皆應-恆亨無咎-利貞。久於其道也。天地之道-恆久而不已也。利有攸往-終則有始也。日月得天而能久照-四時變化而能久成。聖人久於其道而天下化成。觀其所恆-而天地萬物之情可見矣。" aria-label="Permalink to “彖曰：恆，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆亨無咎，利貞。久於其道也。天地之道，恆久而不已也。利有攸往，終則有始也。日月得天而能久照，四時變化而能久成。聖人久於其道而天下化成。觀其所恆，而天地萬物之情可見矣。”">​</a></h3><p>恆亨無咎，利貞，久於其道無不通也。行而可久，必無咎也。常久之利，利居貞也。</p><h3 id="象曰-雷風-恆。君子以立不易方。" tabindex="-1">象曰：雷風，恆。君子以立不易方。 <a class="header-anchor" href="#象曰-雷風-恆。君子以立不易方。" aria-label="Permalink to “象曰：雷風，恆。君子以立不易方。”">​</a></h3><h3 id="初六-浚恆-貞兇-無攸利-象曰-浚恆之兇-始求深也。" tabindex="-1">初六：浚恆，貞兇，無攸利 象曰：浚恆之兇，始求深也。 <a class="header-anchor" href="#初六-浚恆-貞兇-無攸利-象曰-浚恆之兇-始求深也。" aria-label="Permalink to “初六：浚恆，貞兇，無攸利 象曰：浚恆之兇，始求深也。”">​</a></h3><h3 id="九二-悔亡-象曰-九二悔亡-能久中也。" tabindex="-1">九二：悔亡 象曰：九二悔亡，能久中也。 <a class="header-anchor" href="#九二-悔亡-象曰-九二悔亡-能久中也。" aria-label="Permalink to “九二：悔亡 象曰：九二悔亡，能久中也。”">​</a></h3><h3 id="九三-不恆其德-或承之羞-貞吝-象曰-不恆其德-無所容也。" tabindex="-1">九三：不恆其德，或承之羞，貞吝 象曰：不恆其德，無所容也。 <a class="header-anchor" href="#九三-不恆其德-或承之羞-貞吝-象曰-不恆其德-無所容也。" aria-label="Permalink to “九三：不恆其德，或承之羞，貞吝 象曰：不恆其德，無所容也。”">​</a></h3><h3 id="九四-田無禽-象曰-久非其位-安得禽也。" tabindex="-1">九四：田無禽 象曰：久非其位，安得禽也。 <a class="header-anchor" href="#九四-田無禽-象曰-久非其位-安得禽也。" aria-label="Permalink to “九四：田無禽 象曰：久非其位，安得禽也。”">​</a></h3><h3 id="六五-恆其德-貞-婦人吉-夫子兇-象曰-婦人貞吉-從一而終也。夫子制義-從婦兇也。" tabindex="-1">六五：恆其德，貞，婦人吉，夫子兇 象曰：婦人貞吉，從一而終也。夫子制義，從婦兇也。 <a class="header-anchor" href="#六五-恆其德-貞-婦人吉-夫子兇-象曰-婦人貞吉-從一而終也。夫子制義-從婦兇也。" aria-label="Permalink to “六五：恆其德，貞，婦人吉，夫子兇 象曰：婦人貞吉，從一而終也。夫子制義，從婦兇也。”">​</a></h3><h3 id="上六-振恆-兇-象曰-振恆在上-大無功也。" tabindex="-1">上六：振恆，兇 象曰：振恆在上，大無功也。 <a class="header-anchor" href="#上六-振恆-兇-象曰-振恆在上-大無功也。" aria-label="Permalink to “上六：振恆，兇 象曰：振恆在上，大無功也。”">​</a></h3><p>振者，木之搖落也。上以柔弱之質，當恆久之終，體動而應風搖落之象也。常久之道，由茲而墜，故曰大無功也。</p>',11)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
